-- ── Instruments ──────────────────────────────────────────────────────────────
-- current_price here is a hardcoded placeholder, not an observed quote, so updated_at is
-- backdated to the epoch rather than defaulting to NOW(). A NOW() default would claim the
-- placeholder was just observed, and InstrumentService.refreshPriceIfStale returns the
-- stored price untouched while it is younger than quote.refresh-threshold-seconds — so a
-- buy placed shortly after seeding would execute against the placeholder. Backdating makes
-- every seeded row stale on sight, forcing a live refresh before the first trade.
INSERT INTO instruments (instrument_id, ticker, "name", exchange_id, price_scale, current_price, updated_at) VALUES
    ('b2000000-0000-0000-0000-000000000001', 'AAPL',  'Apple Inc.',          'NASDAQ',1.00000000, 229.0000, 'epoch'),
    ('b2000000-0000-0000-0000-000000000002', 'GOOGL', 'Alphabet Inc.',       'NASDAQ',1.00000000, 176.5000, 'epoch'),
    ('b2000000-0000-0000-0000-000000000003', 'MSFT',  'Microsoft Corp.',     'NASDAQ',1.00000000, 430.2500, 'epoch'),
    ('b2000000-0000-0000-0000-000000000004', 'TSLA',  'Tesla Inc.',          'NASDAQ',1.00000000, 254.7500, 'epoch'),
    ('b2000000-0000-0000-0000-000000000005', 'AMZN',  'Amazon.com Inc.',     'NASDAQ',1.00000000, 196.0000, 'epoch'),
    ('b2000000-0000-0000-0000-000000000006', 'NVDA',  'NVIDIA Corp.',        'NASDAQ',1.00000000, 138.2500, 'epoch'),
    ('b2000000-0000-0000-0000-000000000007', 'META',  'Meta Platforms Inc.', 'NASDAQ',1.00000000, 575.5000, 'epoch'),
    ('b2000000-0000-0000-0000-000000000008', 'BTC-USD',  'Bitcoin US dollar', 'CRYPTO',1.00000000, 575.5000, 'epoch')
ON CONFLICT DO NOTHING;


-- Backdate any seeded row that is still carrying its placeholder price. data.sql runs on
-- every startup but the insert above is ON CONFLICT DO NOTHING, so a database seeded before
-- this change would otherwise keep its NOW() timestamp and stay exposed to the same window.
-- Only rows whose price has never been refreshed match, so a live price is never discarded.
UPDATE instruments SET updated_at = 'epoch'
WHERE updated_at > 'epoch'
  AND (instrument_id, current_price) IN (
    ('b2000000-0000-0000-0000-000000000001'::uuid, 229.0000),
    ('b2000000-0000-0000-0000-000000000002'::uuid, 176.5000),
    ('b2000000-0000-0000-0000-000000000003'::uuid, 430.2500),
    ('b2000000-0000-0000-0000-000000000004'::uuid, 254.7500),
    ('b2000000-0000-0000-0000-000000000005'::uuid, 196.0000),
    ('b2000000-0000-0000-0000-000000000006'::uuid, 138.2500),
    ('b2000000-0000-0000-0000-000000000007'::uuid, 575.5000),
    ('b2000000-0000-0000-0000-000000000008'::uuid, 575.5000)
  );

-- ── Holdings (portfolio holdings) ────────────────────────────────────────────
-- These are the net positions of the seed trades below. They are loaded only into a
-- database with no trades yet: once trading starts, a holding that has been sold out is
-- deleted, and reloading it on the next restart would bring the shares back.
INSERT INTO holdings (account_id, instrument_id, quantity)
SELECT seed.account_id::uuid, seed.instrument_id::uuid, seed.quantity
FROM (VALUES
    -- Alice holds AAPL, GOOGL, MSFT
    ('d4000000-0000-0000-0000-000000000001', 'b2000000-0000-0000-0000-000000000001', 15.00000000),
    ('d4000000-0000-0000-0000-000000000001', 'b2000000-0000-0000-0000-000000000002', 10.00000000),
    ('d4000000-0000-0000-0000-000000000001', 'b2000000-0000-0000-0000-000000000003',  5.00000000),
    -- Bob holds TSLA, AMZN, NVDA, MSFT
    ('d4000000-0000-0000-0000-000000000002', 'b2000000-0000-0000-0000-000000000004', 20.00000000),
    ('d4000000-0000-0000-0000-000000000002', 'b2000000-0000-0000-0000-000000000005', 12.00000000),
    ('d4000000-0000-0000-0000-000000000002', 'b2000000-0000-0000-0000-000000000006', 30.00000000),
    ('d4000000-0000-0000-0000-000000000002', 'b2000000-0000-0000-0000-000000000003',  4.00000000),
    -- Charlie holds META, AAPL
    ('d4000000-0000-0000-0000-000000000003', 'b2000000-0000-0000-0000-000000000007',  8.00000000),
    ('d4000000-0000-0000-0000-000000000003', 'b2000000-0000-0000-0000-000000000001', 25.00000000)
) AS seed(account_id, instrument_id, quantity)
WHERE NOT EXISTS (SELECT 1 FROM trades)
ON CONFLICT DO NOTHING;

